package com.novara.banking.statement;
import com.novara.banking.identity.CurrentIdentity.FederatedIdentity;import org.springframework.beans.factory.annotation.Value;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.*;
@Service public class DocumentRateLimitService{private final JdbcClient jdbc;private final int generationLimit,downloadLimit;private final Duration window;public DocumentRateLimitService(JdbcClient jdbc,@Value("${novara.statements.generation-limit:10}")int generationLimit,@Value("${novara.statements.download-limit:30}")int downloadLimit,@Value("${novara.statements.rate-window:PT1M}")Duration window){this.jdbc=jdbc;this.generationLimit=generationLimit;this.downloadLimit=downloadLimit;this.window=window;}
 @Transactional public void generation(FederatedIdentity i){check(i,"GENERATION",generationLimit);}@Transactional public void download(FederatedIdentity i){check(i,"DOWNLOAD",downloadLimit);}private void check(FederatedIdentity i,String endpoint,int limit){long customer=jdbc.sql("SELECT id FROM customers WHERE identity_issuer=:issuer AND identity_subject=:subject").param("issuer",i.issuer()).param("subject",i.subject()).query(Long.class).optional().orElse(-1L);if(customer<0)return;Instant now=Instant.now();long seconds=window.toSeconds();Instant bucket=Instant.ofEpochSecond((now.getEpochSecond()/seconds)*seconds);int count=jdbc.sql("INSERT INTO document_rate_limits(customer_id,endpoint,window_started_at,request_count) VALUES(:c,:e,:w,1) ON CONFLICT(customer_id,endpoint,window_started_at) DO UPDATE SET request_count=document_rate_limits.request_count+1 RETURNING request_count").param("c",customer).param("e",endpoint).param("w",java.sql.Timestamp.from(bucket)).query(Integer.class).single();if(count>limit)throw new DocumentRateLimitException(Math.max(1,bucket.plus(window).getEpochSecond()-now.getEpochSecond()));}}
